 14→// hookManager describes an external hook manager detected in a repository.
 15→type hookManager struct {
 16→	Name            string // "Husky", "Lefthook", "pre-commit", "Overcommit"
 17→	ConfigPath      string // relative path that triggered detection (e.g., ".husky/")
 18→	OverwritesHooks bool   // true if the tool will overwrite Entire's hooks on reinstall
 19→}
 20→
 21→// detectHookManagers checks the repository root for known hook manager config
 22→// files/directories. Detection is filesystem-only (os.Stat, no file reads).
 23→func detectHookManagers(repoRoot string) []hookManager {
 24→	var managers []hookManager
 25→
 26→	checks := []hookManager{
 27→		{"Husky", ".husky/", true},
 28→		{"pre-commit", ".pre-commit-config.yaml", false},
 29→		{"Overcommit", ".overcommit.yml", false},
 30→	}
 31→
 32→	// Lefthook supports {.,}lefthook{,-local}.{yml,yaml,json,toml}
 33→	for _, prefix := range []string{"", "."} {
 34→		for _, variant := range []string{"", "-local"} {
 35→			for _, ext := range []string{"yml", "yaml", "json", "toml"} {
 36→				name := prefix + "lefthook" + variant + "." + ext
 37→				checks = append(checks, hookManager{"Lefthook", name, false})
 38→			}
 39→		}
 40→	}
 41→
 42→	seen := make(map[string]bool)
 43→	for _, c := range checks {
 44→		path := filepath.Join(repoRoot, c.ConfigPath)
 45→		if _, err := os.Stat(path); err == nil {
 46→			if seen[c.Name] {
 47→				continue // e.g., lefthook.yml and .lefthook.yml both present
 48→			}
 49→			seen[c.Name] = true
 50→			managers = append(managers, c)
 51→		}
 52→	}
 53→
 54→	return managers
 55→}
