 57→// hookManagerWarning builds a warning string for detected hook managers.
 58→// cmdPrefix is the CLI command prefix (e.g., "entire" or "go run ./cmd/entire/main.go").
 59→func hookManagerWarning(managers []hookManager, cmdPrefix string) string {
 60→	if len(managers) == 0 {
 61→		return ""
 62→	}
 63→
 64→	var b strings.Builder
 65→
 66→	specs := buildHookSpecs(cmdPrefix)
 67→
 68→	for _, m := range managers {
 69→		if m.OverwritesHooks {
 70→			fmt.Fprintf(&b, "Warning: %s detected (%s)\n", m.Name, m.ConfigPath)
 71→			fmt.Fprintf(&b, "\n")
 72→			fmt.Fprintf(&b, "  %s may overwrite hooks installed by Entire on npm install.\n", m.Name)
 73→			fmt.Fprintf(&b, "  To make Entire hooks permanent, add these lines to your %s hook files:\n", m.Name)
 74→			fmt.Fprintf(&b, "\n")
 75→
 76→			// Use the config path as the hook directory prefix for hook files.
 77→			// For Husky, this is typically ".husky/" where hook scripts are stored.
 78→			hookDir := m.ConfigPath
 79→
 80→			for _, spec := range specs {
 81→				cmdLine := extractCommandLine(spec.content)
 82→				if cmdLine == "" {
 83→					continue
 84→				}
 85→				fmt.Fprintf(&b, "    %s%s:\n", hookDir, spec.name)
 86→				fmt.Fprintf(&b, "      %s\n", cmdLine)
 87→				fmt.Fprintf(&b, "\n")
 88→			}
 89→		} else {
 90→			fmt.Fprintf(&b, "Note: %s detected (%s)\n", m.Name, m.ConfigPath)
 91→			fmt.Fprintf(&b, "\n")
 92→			fmt.Fprintf(&b, "  If %s reinstalls hooks, run 'entire enable' to restore Entire's hooks.\n", m.Name)
 93→			fmt.Fprintf(&b, "\n")
 94→		}
 95→	}
 96→
 97→	return b.String()
 98→}
