100→// extractCommandLine returns the first non-shebang, non-comment, non-empty line
101→// from a hook script. This is the actual command invocation line.
102→func extractCommandLine(hookContent string) string {
103→	for _, line := range strings.Split(hookContent, "\n") {
104→		trimmed := strings.TrimSpace(line)
105→		if trimmed == "" || strings.HasPrefix(trimmed, "#") {
106→			continue
107→		}
108→		return trimmed
109→	}
110→	return ""
111→}
