113→// CheckAndWarnHookManagers detects external hook managers and writes a warning
114→// to w if any are found.
115→// localDev controls whether the warning references "go run" or the "entire" binary.
116→// absolutePath embeds the full binary path for GUI git clients.
117→func CheckAndWarnHookManagers(ctx context.Context, w io.Writer, localDev, absolutePath bool) {
118→	repoRoot, err := paths.WorktreeRoot(ctx)
119→	if err != nil {
120→		return
121→	}
122→
123→	managers := detectHookManagers(repoRoot)
124→	if len(managers) == 0 {
125→		return
126→	}
127→
128→	cmdPrefix, err := hookCmdPrefix(localDev, absolutePath)
129→	if err != nil {
130→		// Best-effort: hook manager warnings are advisory, skip on resolution failure
131→		return
132→	}
133→	warning := hookManagerWarning(managers, cmdPrefix)
134→	if warning != "" {
135→		fmt.Fprintln(w)
136→		fmt.Fprint(w, warning)
137→	}
138→}
