 39→// LoadSessionState loads the session state for the given session ID.
 40→// Returns (nil, nil) when session file doesn't exist or session is stale (not an error condition).
 41→// Stale sessions are automatically deleted by the underlying StateStore.
 42→func LoadSessionState(ctx context.Context, sessionID string) (*SessionState, error) {
 43→	store, err := session.NewStateStore(ctx)
 44→	if err != nil {
 45→		return nil, fmt.Errorf("failed to create state store: %w", err)
 46→	}
 47→
 48→	state, err := store.Load(ctx, sessionID)
 49→	if err != nil {
 50→		return nil, fmt.Errorf("failed to load session state: %w", err)
 51→	}
 52→	return state, nil
 53→}
