 55→// SaveSessionState saves the session state atomically.
 56→func SaveSessionState(ctx context.Context, state *SessionState) error {
 57→	// Validate session ID to prevent path traversal
 58→	if err := validation.ValidateSessionID(state.SessionID); err != nil {
 59→		return fmt.Errorf("invalid session ID: %w", err)
 60→	}
 61→
 62→	stateDir, err := getSessionStateDir(ctx)
 63→	if err != nil {
 64→		return fmt.Errorf("failed to get session state directory: %w", err)
 65→	}
 66→
 67→	if err := os.MkdirAll(stateDir, 0o750); err != nil {
 68→		return fmt.Errorf("failed to create session state directory: %w", err)
 69→	}
 70→
 71→	data, err := jsonutil.MarshalIndentWithNewline(state, "", "  ")
 72→	if err != nil {
 73→		return fmt.Errorf("failed to marshal session state: %w", err)
 74→	}
 75→
 76→	stateFile, err := sessionStateFile(ctx, state.SessionID)
 77→	if err != nil {
 78→		return fmt.Errorf("failed to get session state file path: %w", err)
 79→	}
 80→
 81→	// Atomic write: write to temp file, then rename
 82→	tmpFile := stateFile + ".tmp"
 83→	if err := os.WriteFile(tmpFile, data, 0o600); err != nil {
 84→		return fmt.Errorf("failed to write session state: %w", err)
 85→	}
 86→	if err := os.Rename(tmpFile, stateFile); err != nil {
 87→		return fmt.Errorf("failed to rename session state file: %w", err)
 88→	}
 89→	return nil
 90→}
