 92→// ListSessionStates returns all session states from the state directory.
 93→// This is a package-level function that doesn't require a specific strategy instance.
 94→func ListSessionStates(ctx context.Context) ([]*SessionState, error) {
 95→	store, err := session.NewStateStore(ctx)
 96→	if err != nil {
 97→		return nil, fmt.Errorf("failed to create state store: %w", err)
 98→	}
 99→
100→	states, err := store.List(ctx)
101→	if err != nil {
102→		return nil, fmt.Errorf("failed to list session states: %w", err)
103→	}
104→	return states, nil
