107→// FindMostRecentSession returns the session ID of the most recently interacted session
108→// (by LastInteractionTime) in the current worktree. Returns empty string if no sessions exist.
109→// Scoping to the current worktree prevents cross-worktree pollution in log routing.
110→// Falls back to unfiltered search if the worktree path can't be determined.
111→func FindMostRecentSession(ctx context.Context) string {
112→	states, err := ListSessionStates(ctx)
113→	if err != nil || len(states) == 0 {
114→		return ""
115→	}
116→
117→	// Scope to current worktree to prevent cross-worktree pollution.
118→	worktreePath, wpErr := paths.WorktreeRoot(ctx)
119→	if wpErr == nil && worktreePath != "" {
120→		var filtered []*SessionState
121→		for _, s := range states {
122→			if s.WorktreePath == worktreePath {
123→				filtered = append(filtered, s)
124→			}
125→		}
126→		if len(filtered) > 0 {
127→			states = filtered
128→		}
129→		// If no sessions match the worktree, fall back to all sessions
130→	}
131→
132→	var best *SessionState
133→	for _, s := range states {
134→		if s.LastInteractionTime == nil {
135→			continue
136→		}
137→		if best == nil || s.LastInteractionTime.After(*best.LastInteractionTime) {
138→			best = s
139→		}
140→	}
141→	if best != nil {
142→		return best.SessionID
143→	}
144→
145→	// Fallback: return most recently started session
146→	for _, s := range states {
147→		if best == nil || s.StartedAt.After(best.StartedAt) {
148→			best = s
149→		}
150→	}
151→	if best != nil {
152→		return best.SessionID
153→	}
154→	return ""
155→}
