157→// TransitionAndLog runs a session phase transition, applies actions via the
158→// handler, and logs the transition. Returns the first handler error from
159→// ApplyTransition (if any) so callers can surface it. The error is also
160→// logged internally for diagnostics.
161→// This is the single entry point for all state machine transitions to ensure
162→// consistent logging of phase changes.
163→func TransitionAndLog(goCtx context.Context, state *SessionState, event session.Event, ctx session.TransitionContext, handler session.ActionHandler) error {
164→	oldPhase := state.Phase
165→	result := session.Transition(oldPhase, event, ctx)
166→	logCtx := logging.WithComponent(goCtx, "session")
167→
168→	handlerErr := session.ApplyTransition(goCtx, state, result, handler)
169→	if handlerErr != nil {
170→		logging.Error(logCtx, "action handler error during transition",
171→			slog.String("session_id", state.SessionID),
172→			slog.String("event", event.String()),
173→			slog.Any("error", handlerErr),
174→		)
175→	}
176→
177→	if result.NewPhase != oldPhase {
178→		logging.Info(logCtx, "phase transition",
179→			slog.String("session_id", state.SessionID),
180→			slog.String("event", event.String()),
181→			slog.String("from", string(oldPhase)),
182→			slog.String("to", string(result.NewPhase)),
183→		)
184→	} else {
185→		logging.Debug(logCtx, "phase unchanged",
186→			slog.String("session_id", state.SessionID),
187→			slog.String("event", event.String()),
188→			slog.String("phase", string(result.NewPhase)),
189→			slog.Any("result", result),
190→		)
191→	}
192→
193→	if handlerErr != nil {
194→		return fmt.Errorf("transition %s: %w", event, handlerErr)
195→	}
196→	return nil
197→}
