199→// ClearSessionState removes the session state file for the given session ID.
200→func ClearSessionState(ctx context.Context, sessionID string) error {
201→	// Validate session ID to prevent path traversal
202→	if err := validation.ValidateSessionID(sessionID); err != nil {
203→		return fmt.Errorf("invalid session ID: %w", err)
204→	}
205→
206→	stateFile, err := sessionStateFile(ctx, sessionID)
207→	if err != nil {
208→		return fmt.Errorf("failed to get session state file path: %w", err)
209→	}
210→
211→	if err := os.Remove(stateFile); err != nil {
212→		if os.IsNotExist(err) {
213→			return nil // Already gone, not an error
214→		}
215→		return fmt.Errorf("failed to remove session state file: %w", err)
216→	}
217→	return nil
218→}
